import functools
import threading
import time


def rate_limit(calls_per_second):
    interval = 1.0 / calls_per_second
    lock = threading.Lock()
    last = [0.0]

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            with lock:
                wait = interval - (time.monotonic() - last[0])
                if wait > 0:
                    time.sleep(wait)
                last[0] = time.monotonic()
            return func(*args, **kwargs)
        return wrapper
    return decorator

