from pathlib import Path


def total_size(path):
    return sum(item.stat().st_size for item in Path(path).rglob('*') if item.is_file())

def unique(items):
    seen = set()
    out = []
    for item in items:
        if item in seen:
            continue
        seen.add(item)
        out.append(item)
    return out

